    raise AssertionError('expected ValueError')

class Probe:
    def __init__(self):
        self.started = False
        self.values = iter(range(5))
    def __iter__(self):
        self.started = True
        return self
    def __next__(self):
        return next(self.values)

probe = Probe()
groups = batched(probe, 2)
